# owner: platform
import unittest

from hourglass.rounding import round_span, rounded_labels, span_label
from hourglass.models import Span


class RoundSpanTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        self.assertEqual(round_span(Span(542, 1033), 15), Span(540, 1035))

    def test_halfway_goes_up(self):
        self.assertEqual(round_span(Span(67, 127), 15), Span(75, 120))

    def test_step_of_one_changes_nothing(self):
        self.assertEqual(round_span(Span(541, 1000), 1), Span(541, 1000))

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(540, 544), 15)


class LabelTests(unittest.TestCase):
    def test_label(self):
        self.assertEqual(span_label(Span(540, 1035)), "09:00-17:15 (8h 15m)")

    def test_label_under_an_hour(self):
        self.assertEqual(span_label(Span(540, 585)), "09:00-09:45 (0h 45m)")

    def test_rounded_labels(self):
        spans = [Span(542, 1033), Span(600, 660)]
        self.assertEqual(
            rounded_labels(spans, 15),
            ["09:00-17:15 (8h 15m)", "10:00-11:00 (1h 00m)"]
        )

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 30), [])


class BadStepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                rounded_labels([Span(60, 120)], step)

    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)

    def test_good_steps_accepted(self):
        for step in (1, 5, 10, 15, 20, 30, 60):
            self.assertEqual(len(rounded_labels([Span(60, 180)], step)), 1)
